111	/**
112	 * Fetch all workspaces for matching projects and collect status data for the
113	 * given repository. Uses `Promise.allSettled` at each fan-out level so that
114	 * individual fetch failures do not abort the entire load.
115	 *
116	 * @param {string}   repoId       - The repository ID to look for.
117	 * @param {Object[]} allProjects  - Raw project list from `api.projects.list()`.
118	 * @returns {Promise<{ rows: WorkspaceRowDescriptor[], anyFailed: boolean }>}
119	 */
120	async function loadWorkspaceRows(repoId, allProjects) {
121	    let anyFailed = false;
122	
123	    // Step 1: Fetch full project data for all projects in parallel.
124	    const projectResults = await Promise.allSettled(
125	        allProjects.map((p) => {
126	            const pid = p.Id || p.id || '';
127	            return api.projects.get(pid).then((full) => ({ pid, full }));
128	        }),
129	    );
130	
131	    // Step 2: Filter projects that contain this repo.
132	    const matchingProjects = [];
133	    for (const result of projectResults) {
134	        if (result.status === 'rejected') {
135	            anyFailed = true;
136	            continue;
137	        }
138	        const { pid, full } = result.value;
139	        const project = normaliseProject(full);
140	        const contains = project.repositories.some((r) => {
141	            const rid = (typeof r === 'string') ? r : (r.Id || r.id || r.RepositoryId || r.repositoryId || '');
142	            return rid === repoId;
143	        });
144	        if (contains) {
145	            matchingProjects.push({ pid, project });
146	        }
147	    }
148	
149	    // Step 3: Fetch workspaces for each matching project in parallel.
150	    const workspaceResults = await Promise.allSettled(
151	        matchingProjects.map(({ pid }) =>
152	            api.workspaces.list(pid).then((wsList) => ({ pid, wsList })),
153	        ),
154	    );
155	
156	    // Step 4: Fetch status per workspace in parallel.
157	    const statusFetchTasks = [];
158	    for (const result of workspaceResults) {
159	        if (result.status === 'rejected') {
160	            anyFailed = true;
161	            continue;
162	        }
163	        const { pid, wsList } = result.value;
164	        const projectName = matchingProjects.find((mp) => mp.pid === pid)?.project.name || pid;
165	
166	        for (const rawWs of (wsList || [])) {
167	            const ws = normaliseWorkspace(rawWs);
168	            const wid = ws.id;
169	            if (!wid) continue;
170	
171	            statusFetchTasks.push(
172	                api.status.get(pid, wid)
173	                    .then((statusMap) => ({
174	                        pid,
175	                        projectName,
176	                        wid,
177	                        isStable:    wid === STABLE_WS_ID,
178	                        initialized: ws.initialized,
179	                        statusInfo:  (statusMap && statusMap[repoId]) ? statusMap[repoId] : null,
180	                    }))
181	                    .catch(() => {
182	                        // Status fetch failed — include the row but without status data.
183	                        return {
184	                            pid,
185	                            projectName,
186	                            wid,
187	                            isStable:    wid === STABLE_WS_ID,
188	                            initialized: ws.initialized,
189	                            statusInfo:  null,
190	                        };
191	                    }),
192	            );
193	        }
194	    }
195	
196	    const statusResults = await Promise.allSettled(statusFetchTasks);
197	
198	    const rows = [];
199	    for (const result of statusResults) {
200	        if (result.status === 'rejected') {
201	            anyFailed = true;
202	            continue;
203	        }
204	        rows.push(result.value);
205	    }
206	
207	    return { rows, anyFailed };
208	}
